annotations.length:
#[cfg_attr(kani,kani::modifies(Rc::as_ptr(&self.data).cast_mut().cast::<isize>()))]
#[cfg_attr(kani,kani::ensures(|result| {
    let before=old(unsafe{(*Rc::as_ptr(&self.data).cast::<std::cell::Cell<isize>>()).get()});let now=unsafe{(*Rc::as_ptr(&self.data).cast::<std::cell::Cell<isize>>()).get()};
    match result {
        Ok(n)=>before>=0 && before<isize::MAX && *n==unsafe{(&*self.data.as_ptr()).len()} && now==before,
        Err(e)=>matches!(e,ProgramError::AccountBorrowFailed) && (before<0 || before==isize::MAX) && now==before,
    }
}))]

annotations.shared:
#[cfg_attr(kani,kani::modifies(Rc::as_ptr(&self.data).cast_mut().cast::<isize>()))]
#[cfg_attr(kani,kani::ensures(|result| {
    let before=old(unsafe{(*Rc::as_ptr(&self.data).cast::<std::cell::Cell<isize>>()).get()});let now=unsafe{(*Rc::as_ptr(&self.data).cast::<std::cell::Cell<isize>>()).get()};
    match result {
        Ok(guard)=>before>=0 && before<isize::MAX && now==before+1 && std::mem::size_of_val(guard)==2*std::mem::size_of::<usize>() &&
            unsafe{*(guard as *const _ as *const usize)}==self.data.as_ptr() as usize &&
            unsafe{*(guard as *const _ as *const usize).add(1)}==Rc::as_ptr(&self.data) as usize,
        Err(e)=>matches!(e,ProgramError::AccountBorrowFailed) && (before<0 || before==isize::MAX) && now==before,
    }
}))]

annotations.exclusive:
#[cfg_attr(kani,kani::modifies(Rc::as_ptr(&self.data).cast_mut().cast::<isize>()))]
#[cfg_attr(kani,kani::ensures(|result| {
    let before=old(unsafe{(*Rc::as_ptr(&self.data).cast::<std::cell::Cell<isize>>()).get()});let now=unsafe{(*Rc::as_ptr(&self.data).cast::<std::cell::Cell<isize>>()).get()};
    match result {
        Ok(guard)=>before==0 && now == -1 && std::mem::size_of_val(guard)==2*std::mem::size_of::<usize>() &&
            unsafe{*(guard as *const _ as *const usize)}==self.data.as_ptr() as usize &&
            unsafe{*(guard as *const _ as *const usize).add(1)}==Rc::as_ptr(&self.data) as usize,
        Err(e)=>matches!(e,ProgramError::AccountBorrowFailed) && (before!=0) && now==before,
    }
}))]
